<?php
namespace AutoDealership\Portal;
use AutoDealership\Database\Schema;
use AutoDealership\Database\Transaction;
use AutoDealership\Security\BranchScope;
defined('ABSPATH') || exit;

/** Account-owned projections of the existing sales system; no financial state is invented here. */
final class CustomerJourney {
	public static function boot():void {
		add_action('wp_enqueue_scripts',static function(){if(PortalAccess::ready()){wp_enqueue_script('adc-favorite-heart',plugins_url('assets/js/customer-favorites.js',ADC_FILE),array(),ADC_VERSION,true);}});
		add_action('admin_post_adc_customer_journey',array(self::class,'submit'));
		add_action('admin_post_nopriv_adc_customer_journey',static function(){wp_safe_redirect(PortalAccess::url('overview'));exit;});
	}
	public static function sections(array $sections):array {return array_slice($sections,0,3,true)+array('favorites'=>['سياراتي المفضلة','Saved cars'],'purchases'=>['رحلة الشراء','My purchases'],'documents'=>['العقود والفواتير','Contracts & invoices'])+array_slice($sections,3,null,true);}
	public static function form(string $operation,array $fields=array(),bool $upload=false):void {
		echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="adc-journey-form"'.($upload?' enctype="multipart/form-data"':'').'>';echo str_replace('id="_wpnonce"','id="'.esc_attr(wp_unique_id('adc-journey-nonce-')).'"',wp_nonce_field('adc_customer_journey','_wpnonce',true,false));foreach(array_merge(array('action'=>'adc_customer_journey','operation'=>$operation,'portal_scope'=>'personal','lang'=>PortalAccess::language()),$fields) as $key=>$value){echo '<input type="hidden" name="'.esc_attr($key).'" value="'.esc_attr((string)$value).'">';}
	}
	public static function sale(int $id,bool $staff=false):?array {
		global $wpdb;if(!PortalAccess::ready()||!get_current_user_id()){return null;}
		$row=$wpdb->get_row($wpdb->prepare('SELECT s.id,s.status,s.owner_user_id,s.approved_by,c.account_user_id,c.merged_into_id,q.branch_id,q.final_amount,q.quote_number,q.status quote_status,q.valid_until,r.status reservation_status,r.expires_at,d.status delivery_status,d.delivered_at,r.deposit_amount FROM '.Schema::table('sales').' s JOIN '.Schema::table('customers').' c ON c.id=s.customer_id JOIN '.Schema::table('quotations').' q ON q.id=s.quotation_id LEFT JOIN '.Schema::table('reservations').' r ON r.id=s.reservation_id LEFT JOIN '.Schema::table('deliveries').' d ON d.sale_id=s.id WHERE s.id=%d',$id),ARRAY_A);
		if(!$row||$row['merged_into_id']){return null;}
		if(!$staff){return (int)$row['account_user_id']===get_current_user_id()?$row:null;}
		return (current_user_can('manage_options')||(current_user_can('adc_publish_customer_documents')&&BranchScope::allows((int)$row['branch_id'])&&(current_user_can('adc_view_branch_leads')||current_user_can('adc_view_finance')||(int)$row['owner_user_id']===get_current_user_id())))?$row:null;
	}
	public static function favorite(int $car,bool $save) {
		global $wpdb;$user=get_current_user_id();if(!PortalAccess::ready()||!$user){return PortalAccess::error('adc_portal_forbidden',403);}
		if($save&&('car'!==get_post_type($car)||!\AutoDealership\Inventory\PublicCatalog::is_post_publicly_eligible($car))){return PortalAccess::error('adc_portal_input');}
		if(!Transaction::begin()){return PortalAccess::error();}$locked=$wpdb->query($wpdb->prepare('INSERT INTO '.PortalAccess::table('presence').'(user_id,session_key,thread_id,available,typing_until,seen_at) VALUES(%d,%s,0,0,0,%d) ON DUPLICATE KEY UPDATE seen_at=VALUES(seen_at)',$user,hash('sha256','portal-favorites-mutex'),time()));if(false===$locked){$wpdb->query('ROLLBACK');return PortalAccess::error();}
		if($save){$exists=$wpdb->get_var($wpdb->prepare('SELECT car_id FROM '.PortalAccess::table('favorites').' WHERE user_id=%d AND car_id=%d',$user,$car));if(!$exists&&(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.PortalAccess::table('favorites').' WHERE user_id=%d',$user))>=200){$wpdb->query('ROLLBACK');return PortalAccess::error('adc_portal_input');}$ok=$wpdb->query($wpdb->prepare('INSERT INTO '.PortalAccess::table('favorites').'(user_id,car_id,created_at) VALUES(%d,%d,%s) ON DUPLICATE KEY UPDATE car_id=car_id',$user,$car,current_time('mysql',true)));}else{$ok=$wpdb->delete(PortalAccess::table('favorites'),array('user_id'=>$user,'car_id'=>$car));}
		if(false===$ok||!Transaction::commit(static fn()=>PortalAccess::audit($save?'favorite_saved':'favorite_removed','car',$car))){$wpdb->query('ROLLBACK');return PortalAccess::error();}return true;
	}
	public static function favorite_button(int $car,bool $icon=false):void {
		if($icon){self::favorite_icon($car);return;}
		if(!PortalAccess::ready()){return;}if(!is_user_logged_in()){echo '<a class="adc-p-button is-secondary adc-save-car" href="'.esc_url(PortalAccess::url('favorites')).'">'.esc_html(PortalAccess::t('حفظ في المفضلة','Save car')).'</a>';return;}
		global $wpdb;$saved=(bool)$wpdb->get_var($wpdb->prepare('SELECT car_id FROM '.PortalAccess::table('favorites').' WHERE user_id=%d AND car_id=%d',get_current_user_id(),$car));self::form('favorite',array('car'=>$car,'save'=>$saved?'0':'1'));PortalView::button($saved?'إزالة من المفضلة':'حفظ في المفضلة',$saved?'Remove saved car':'Save car','is-secondary adc-save-car');echo '</form>';
	}
	private static function favorite_icon(int $car):void {
		if(!PortalAccess::ready()){return;}
		$save=sprintf(PortalAccess::t('حفظ %s في المفضلة','Save %s to favorites'),get_the_title($car));
		$remove=sprintf(PortalAccess::t('إزالة %s من المفضلة','Remove %s from favorites'),get_the_title($car));
		$heart='<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true" focusable="false"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/></svg>';
		if(!is_user_logged_in()){echo '<a class="adc-favorite-heart" href="'.esc_url(PortalAccess::url('favorites')).'" aria-label="'.esc_attr(PortalAccess::t('سجل الدخول لحفظ السيارة في المفضلة','Sign in to save this car')).'" title="'.esc_attr($save).'">'.$heart.'</a>';return;}
		global $wpdb;$saved=(bool)$wpdb->get_var($wpdb->prepare('SELECT car_id FROM '.PortalAccess::table('favorites').' WHERE user_id=%d AND car_id=%d',get_current_user_id(),$car));
		self::form('favorite',array('car'=>$car,'save'=>$saved?'0':'1','favorite_ui'=>'icon'));
		echo '<button type="submit" class="adc-favorite-heart" data-favorite-car="'.(int)$car.'" data-label-save="'.esc_attr($save).'" data-label-remove="'.esc_attr($remove).'" aria-pressed="'.($saved?'true':'false').'" aria-label="'.esc_attr($saved?$remove:$save).'" title="'.esc_attr($saved?$remove:$save).'">'.$heart.'</button></form>';
	}
	public static function favorites():void {
		global $wpdb;$page=max(1,min(10,absint($_GET['portal_page']??1)));$rows=$wpdb->get_col($wpdb->prepare('SELECT car_id FROM '.PortalAccess::table('favorites').' WHERE user_id=%d ORDER BY created_at DESC,car_id DESC LIMIT 21 OFFSET %d',get_current_user_id(),($page-1)*20));
		echo '<p>'.esc_html(PortalAccess::t('سياراتك المحفوظة متاحة عند دخولك من أي جهاز. قد يتغير السعر أو التوفر؛ تواصل مع الفريق للتأكيد.','Your saved cars are available whenever you sign in on any device. Prices and availability may change; ask our team to confirm.')).'</p><div class="adc-p-saved-grid">';if($wpdb->last_error){echo '<p role="alert">'.esc_html(PortalAccess::error()->get_error_message()).'</p>';return;}if(!$rows){PortalView::empty('لم تحفظ أي سيارة بعد. يمكنك حفظ السيارات أثناء التصفح.','No saved cars yet. Save cars while browsing.');}
		foreach(array_slice($rows?:array(),0,20) as $car){$visible=\AutoDealership\Inventory\PublicCatalog::is_post_publicly_eligible((int)$car);echo '<article class="adc-p-card">';if($visible){echo '<a href="'.esc_url(get_permalink($car)).'">'.get_the_post_thumbnail($car,'medium',array('loading'=>'lazy')).'<h3>'.esc_html(get_the_title($car)).'</h3></a>';}else{echo '<h3>'.esc_html(PortalAccess::t('هذه السيارة لم تعد معروضة','This car is no longer listed')).'</h3>';}if($visible){self::saved_details((int)$car);}self::favorite_button((int)$car);echo '</article>';}
		echo '</div>';PortalView::pagination($page,count($rows?:array())>20,PortalAccess::url('favorites'));
	}
	private static function saved_details(int $car):void {
		$model=function_exists('adc_public_vehicle_view')?adc_public_vehicle_view($car):null;if(!$model){return;}
		echo '<div class="adc-p-saved-meta">';
		if(!empty($model['price'])){echo '<span>'.esc_html(function_exists('car_dealer_catalog_format_price')?car_dealer_catalog_format_price($model['price']):$model['price'].' SAR').'</span>';}
		if(!empty($model['year'])){echo '<span>'.esc_html($model['year']).'</span>';}
		if(isset($model['kilometers'])&&''!==$model['kilometers']){echo '<span>'.esc_html(number_format_i18n((int)$model['kilometers']).' '.PortalAccess::t('كم','km')).'</span>';}
		echo '</div><p class="adc-p-help">'.esc_html(PortalAccess::t('معروضة حاليًا؛ أكّد السعر والتوفر مع الفريق.','Currently listed; confirm price and availability with our team.')).'</p><a class="adc-p-button is-secondary" href="'.esc_url(get_permalink($car).'#request-price').'">'.esc_html(PortalAccess::t('التفاصيل والاستفسار','Details & enquiry')).'</a>';
	}
	private static function purchase_next(array $sale):void {
		$status=$sale['status'];
		$labels=array(
			'pending_approval'=>array('بانتظار المعرض: مراجعة واعتماد عملية البيع. يمكنك التواصل مع مستشارك للاستفسار.','Waiting for the dealership to review and approve the sale. Contact your adviser with questions.'),
			'pending_finance'=>array('بانتظار نتيجة التمويل. تواصل مع مستشارك لمعرفة أي متطلبات متبقية.','Waiting for the finance decision. Ask your adviser about any outstanding requirements.'),
			'pending_payment'=>array('راجع المدفوعات المتحقق منها أدناه، ونسّق مع المعرض لاستكمال المطلوب. المدفوعات قيد التحقق لا تدخل في الإجمالي.','Review the verified payments below and coordinate the next steps with the dealership. Payments awaiting verification are excluded.'),
			'ready_for_delivery'=>array('السيارة جاهزة للتسليم. نسّق موعد الاستلام مع فريق المعرض.','The vehicle is ready for delivery. Arrange collection with the dealership.'),
			'delivered'=>array('اكتمل التسليم. يمكنك الرجوع إلى مستندات العملية أو التواصل لخدمة ما بعد البيع.','Delivery is complete. Access your purchase documents or contact us for after-sales support.'),
			'cancelled'=>array('هذه العملية ملغاة. راجع حالة الاسترداد إن وجدت، أو تواصل مع الفريق للاستفسار.','This purchase is cancelled. Review any refund status or contact the team with questions.'),
			'returned'=>array('راجع متابعة المرتجع والاسترداد أسفل تفاصيل العملية.','Review the return and refund information below.')
		);
		echo '<p class="adc-p-purchase-next"><strong>'.esc_html(PortalAccess::t('الخطوة التالية: ','Next step: ')).'</strong>'.esc_html(PortalAccess::t(...($labels[$status]??array('يتابع المعرض تجهيز العملية. راجع المستندات وتواصل مع مستشارك لمعرفة الخطوة المطلوبة.','The dealership is processing your purchase. Review your documents and ask your adviser about the next step.')))).'</p>';
	}
	public static function status(string $status):string {
		$extra=array('returned'=>['تم استلام المرتجع','Return received'],'partial'=>['مدفوع جزئيًا','Partially paid'],'pending'=>['بانتظار المتابعة','Awaiting follow-up'],'not_started'=>['لم تبدأ بعد','Not started'],'pending_finance'=>['بانتظار التمويل','Awaiting finance'],'no_refund_due'=>['لا يوجد مبلغ مستحق للاسترداد','No refund due'],'pending_refund'=>['بانتظار استكمال الاسترداد','Refund pending'],'partially_refunded'=>['تم الاسترداد جزئيًا','Partially refunded'],'refunded'=>['اكتمل الاسترداد','Refund completed']);if(isset($extra[$status])){return PortalAccess::t(...$extra[$status]);}
		$labels=array('draft'=>['مسودة','Draft'],'issued'=>['صادر','Issued'],'accepted'=>['مقبول','Accepted'],'expired'=>['منتهي','Expired'],'confirmed'=>['مؤكد','Confirmed'],'pending_approval'=>['بانتظار الاعتماد','Awaiting approval'],'approved'=>['معتمد','Approved'],'pending_payment'=>['بانتظار الدفع','Awaiting payment'],'paid'=>['مدفوع','Paid'],'ready_for_delivery'=>['جاهز للتسليم','Ready for delivery'],'delivered'=>['تم التسليم','Delivered'],'cancelled'=>['ملغى','Cancelled'],'preparing'=>['قيد التجهيز','Preparing'],'ready'=>['جاهز','Ready'],'submitted'=>['قيد الدراسة','Under review'],'rejected'=>['غير معتمد','Not approved'],'verified'=>['متحقق','Verified'],'completed'=>['مكتمل','Completed'],'converted'=>['تحول إلى بيع','Converted to sale']);return isset($labels[$status])?PortalAccess::t(...$labels[$status]):PortalAccess::t('قيد المتابعة','In progress');
	}
	public static function purchases():void {
		$statuses=array();foreach(array('pending_approval','pending_finance','pending_payment','paid','ready_for_delivery','delivered','cancelled','returned') as $key){$statuses[$key]=self::status($key);}AccountFilters::render('purchases',$statuses);$filters=AccountFilters::values($statuses);$sale=absint($_GET['sale']??0);
		if(!$sale&&!array_filter($filters)){self::before_sale();}
		global $wpdb;$page=max(1,min(10000,absint($_GET['portal_page']??1)));$where='';$args=array(get_current_user_id());
		if($sale){$where.=' AND s.id=%d';$args[]=$sale;echo '<p><a href="'.esc_url(PortalAccess::url('purchases')).'">'.esc_html(PortalAccess::t('كل عمليات الشراء','All purchases')).'</a></p>';}
		if($filters['status']){$where.=' AND s.status=%s';$args[]=$filters['status'];}
		if($filters['search']){$where.=' AND (q.quote_number LIKE %s OR CAST(s.id AS CHAR) LIKE %s)';$like='%'.$wpdb->esc_like($filters['search']).'%';$args[]=$like;$args[]=$like;}
		foreach(array('from'=>'>=','to'=>'<=') as $key=>$operator){if($filters[$key]){$where.=" AND s.created_at $operator %s";$args[]=get_gmt_from_date($filters[$key].('from'===$key?' 00:00:00':' 23:59:59'));}}
		$args[]=($page-1)*10;$ids=$wpdb->get_col($wpdb->prepare('SELECT s.id FROM '.Schema::table('sales').' s JOIN '.Schema::table('customers').' c ON c.id=s.customer_id JOIN '.Schema::table('quotations')." q ON q.id=s.quotation_id WHERE c.account_user_id=%d AND c.merged_into_id IS NULL $where ORDER BY s.id DESC LIMIT 11 OFFSET %d",$args));
		if($wpdb->last_error){echo '<p class="adc-p-notice is-error" role="alert">'.esc_html(PortalAccess::t('تعذر تحميل عمليات الشراء. أعد المحاولة.','Could not load purchases. Please retry.')).'</p>';return;}
		if(!$ids){PortalView::empty('ستظهر رحلة الشراء هنا عند إنشاء عملية بيع مرتبطة بحسابك لدى المعرض.','Your purchase journey will appear when the dealership creates a sale linked to your account.');}
		foreach(array_slice($ids?:array(),0,10) as $id){$s=self::sale((int)$id);if(!$s){continue;}$paid=(int)$wpdb->get_var($wpdb->prepare('SELECT COALESCE(SUM(amount),0) FROM '.Schema::table('payment_confirmations')." WHERE sale_id=%d AND status='verified'",$id))+(int)($s['deposit_amount']??0);$payment_error=(bool)$wpdb->last_error;$finance=$wpdb->get_row($wpdb->prepare('SELECT status,updated_at FROM '.Schema::table('finance_requests').' WHERE sale_id=%d ORDER BY id DESC LIMIT 1',$id),ARRAY_A);if($payment_error||$wpdb->last_error){echo '<p class="adc-p-notice is-error" role="alert">'.esc_html(PortalAccess::error()->get_error_message()).'</p>';continue;}
			echo '<article class="adc-p-card"><header class="adc-p-card-head"><h3>'.esc_html(PortalAccess::t('عملية شراء #','Purchase #').$id.' · '.$s['quote_number']).'</h3><span class="adc-p-badge">'.esc_html(self::status($s['status'])).'</span></header><ol class="adc-p-purchase-timeline">';
			foreach(array(array('عرض السعر','Quotation',$s['quote_status']),array('حجز السيارة','Vehicle reservation',$s['reservation_status']?:'pending'),array('اعتماد البيع','Sale approval',((int)$s['approved_by']?'approved':'pending_approval')),array('التسليم','Delivery',$s['delivery_status']?:'not_started')) as $step){echo '<li data-state="'.esc_attr($step[2]).'"><strong>'.esc_html(PortalAccess::t($step[0],$step[1])).'</strong><span>'.esc_html(self::status($step[2])).'</span></li>';}echo '</ol>';self::purchase_next($s);echo '<p class="adc-p-badge">'.esc_html(self::status($paid>=(int)$s['final_amount']?'paid':($paid>0?'partial':'pending_payment'))).'</p><dl class="adc-p-purchase-details"><dt>'.esc_html(PortalAccess::t('إجمالي عرض السعر','Quotation total')).'</dt><dd>'.esc_html(number_format_i18n((int)$s['final_amount']/100,2).' SAR').'</dd><dt>'.esc_html(PortalAccess::t('المدفوعات المتحقق منها','Verified payments')).'</dt><dd>'.esc_html(number_format_i18n($paid/100,2).' SAR').'</dd>';
			if($finance){echo '<dt>'.esc_html(PortalAccess::t('طلب التمويل','Finance application')).'</dt><dd>'.esc_html(self::status($finance['status'])).'</dd>';}if($s['delivered_at']){echo '<dt>'.esc_html(PortalAccess::t('تاريخ التسليم','Delivered on')).'</dt><dd>'.esc_html(get_date_from_gmt($s['delivered_at'],'Y-m-d')).'</dd>';}echo '</dl>';self::after_sale($s);echo '<p class="adc-p-help">'.esc_html(PortalAccess::t('تعكس هذه البيانات السجلات المعتمدة لدى المعرض. المدفوعات قيد التحقق لا تُحتسب هنا.','This view reflects dealership records. Payments awaiting verification are not included.')).'</p><a class="adc-p-button is-secondary" href="'.esc_url(PortalAccess::url('documents',array('sale'=>$id))).'">'.esc_html(PortalAccess::t('مستندات العملية','Purchase documents')).'</a></article>';
		}
		PortalView::pagination($page,count($ids?:array())>10,PortalAccess::url('purchases',AccountFilters::args()));
	}
	private static function before_sale():void {
		global $wpdb;$quotes=$wpdb->get_results($wpdb->prepare('SELECT q.id,q.quote_number,q.final_amount,q.status,q.valid_until FROM '.Schema::table('quotations').' q JOIN '.Schema::table('customers')." c ON c.id=q.customer_id WHERE c.account_user_id=%d AND c.merged_into_id IS NULL AND q.status<>'draft' AND NOT EXISTS(SELECT 1 FROM ".Schema::table('sales').' s WHERE s.quotation_id=q.id) ORDER BY q.id DESC LIMIT 10',get_current_user_id()),ARRAY_A);
		foreach($quotes?:array() as $quote){echo '<article class="adc-p-card"><h3>'.esc_html(PortalAccess::t('عرض السعر ','Quotation ').$quote['quote_number']).'</h3><span class="adc-p-badge">'.esc_html(self::status($quote['status'])).'</span><p>'.esc_html(number_format_i18n((int)$quote['final_amount']/100,2).' SAR').'</p><p>'.esc_html(PortalAccess::t('صالح حتى: ','Valid until: ').$quote['valid_until']).'</p><p class="adc-p-help">'.esc_html(PortalAccess::t('عرض السعر ليس عقد شراء. تواصل مع مستشارك لمتابعة الخطوات التالية.','A quotation is not a purchase contract. Contact your adviser to discuss the next steps.')).'</p></article>';}
		$reservations=$wpdb->get_results($wpdb->prepare('SELECT r.id,r.status,r.expires_at,r.deposit_amount FROM '.Schema::table('reservations').' r JOIN '.Schema::table('customers').' c ON c.id=r.customer_id WHERE c.account_user_id=%d AND c.merged_into_id IS NULL AND NOT EXISTS(SELECT 1 FROM '.Schema::table('sales').' s WHERE s.reservation_id=r.id) ORDER BY r.id DESC LIMIT 10',get_current_user_id()),ARRAY_A);
		foreach($reservations?:array() as $r){echo '<article class="adc-p-card"><h3>'.esc_html(PortalAccess::t('حجز سيارة #','Vehicle reservation #').$r['id']).'</h3><span class="adc-p-badge">'.esc_html(self::status($r['status'])).'</span><p>'.esc_html(PortalAccess::t('ينتهي في: ','Expires: ').get_date_from_gmt($r['expires_at'],'Y-m-d H:i')).'</p><p>'.esc_html(PortalAccess::t('العربون المسجل: ','Recorded deposit: ').number_format_i18n((int)$r['deposit_amount']/100,2).' SAR').'</p></article>';}
	}
	private static function after_sale(array $sale):void {
		global $wpdb;$id=(int)$sale['id'];$return=$wpdb->get_row($wpdb->prepare('SELECT financial_status,created_at FROM '.Schema::table('vehicle_returns').' WHERE sale_id=%d',$id),ARRAY_A);$cancel=$wpdb->get_row($wpdb->prepare('SELECT financial_status,created_at FROM '.Schema::table('sale_cancellations').' WHERE sale_id=%d',$id),ARRAY_A);$event=$return?:$cancel;if(!$event){return;}
		$refunded=(int)$wpdb->get_var($wpdb->prepare('SELECT COALESCE(SUM(amount),0) FROM '.Schema::table('payment_refunds')." WHERE sale_id=%d AND status='verified' AND currency='SAR'",$id));echo '<section class="adc-p-after-sale"><h4>'.esc_html($return?PortalAccess::t('متابعة المرتجع','Return follow-up'):PortalAccess::t('متابعة إلغاء البيع','Sale cancellation follow-up')).'</h4><p>'.esc_html(self::status($event['financial_status'])).'</p><p>'.esc_html(PortalAccess::t('المبالغ المستردة المتحقق منها: ','Verified refunds: ').number_format_i18n($refunded/100,2).' SAR').'</p></section>';
	}
	public static function documents():void {
		$statuses=array('contract'=>PortalAccess::t('عقود','Contracts'),'invoice'=>PortalAccess::t('فواتير','Invoices'));AccountFilters::render('documents',$statuses);$filters=AccountFilters::values($statuses);
		global $wpdb;$page=max(1,min(10000,absint($_GET['portal_page']??1)));$sale=absint($_GET['sale']??0);$where=$sale?' AND d.sale_id=%d':'';$args=array(get_current_user_id());if($sale){$args[]=$sale;echo '<p><a href="'.esc_url(PortalAccess::url('documents')).'">'.esc_html(PortalAccess::t('كل المستندات','All documents')).'</a></p>';}
		if($filters['status']){$where.=' AND d.kind=%s';$args[]=$filters['status'];}
		if($filters['search']){$where.=' AND (d.title LIKE %s OR d.reference LIKE %s)';$like='%'.$wpdb->esc_like($filters['search']).'%';$args[]=$like;$args[]=$like;}
		foreach(array('from'=>'>=','to'=>'<=') as $key=>$operator){if($filters[$key]){$where.=" AND d.created_at $operator %s";$args[]=get_gmt_from_date($filters[$key].('from'===$key?' 00:00:00':' 23:59:59'));}}$args[]=($page-1)*20;
		$rows=$wpdb->get_results($wpdb->prepare('SELECT d.id,d.sale_id,d.title,d.kind,d.reference,d.file_size,d.created_at FROM '.PortalAccess::table('documents').' d JOIN '.Schema::table('sales').' s ON s.id=d.sale_id JOIN '.Schema::table('customers')." c ON c.id=s.customer_id WHERE c.account_user_id=%d AND c.merged_into_id IS NULL AND d.status='published' $where ORDER BY d.id DESC LIMIT 21 OFFSET %d",$args),ARRAY_A);
		if($wpdb->last_error){echo '<p class="adc-p-notice is-error" role="alert">'.esc_html(PortalAccess::t('تعذر تحميل المستندات. أعد المحاولة.','Could not load documents. Please retry.')).'</p>';return;}
		echo '<p>'.esc_html(PortalAccess::t('المستندات الرسمية التي أتاحها المعرض لعملياتك. تنزيلها لا يُعد توقيعًا أو موافقة تعاقدية.','Official documents shared by the dealership for your purchases. Downloading does not constitute a signature or contractual acceptance.')).'</p>';if(!$rows){PortalView::empty('لا توجد عقود أو فواتير متاحة لحسابك حاليًا أو لا توجد نتائج مطابقة للتصفية.','No shared contracts or invoices, or no results match these filters.');}
		foreach(array_slice($rows?:array(),0,20) as $row){echo '<article class="adc-p-card"><h3>'.esc_html($row['title']).'</h3><p>'.esc_html(('contract'===$row['kind']?PortalAccess::t('عقد','Contract'):PortalAccess::t('فاتورة','Invoice')).' · '.$row['reference'].' · #'.$row['sale_id']).'</p><small>'.esc_html(size_format((int)$row['file_size']).' · '.get_date_from_gmt($row['created_at'],'Y-m-d')).'</small>';self::form('download',array('id'=>$row['id']));PortalView::button('تنزيل PDF','Download PDF');echo '</form></article>';}
		PortalView::pagination($page,count($rows?:array())>20,PortalAccess::url('documents',AccountFilters::args()));
	}
	public static function reschedule_form(int $id):void {
		global $wpdb;if(!PortalAccess::verified()){return;}$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}car_dealer_bookings WHERE id=%d AND user_id=%d",$id,get_current_user_id()),ARRAY_A);if(!$row||!in_array($row['status'],array('pending','confirmed'),true)){return;}$s=PortalOperations::schedule();
		echo '<details class="adc-p-reschedule"><summary>'.esc_html(PortalAccess::t('تغيير الموعد','Change appointment')).'</summary><p>'.esc_html(PortalAccess::t('اختر موعدًا جديدًا. سيعود الحجز إلى انتظار تأكيد الفريق، ويُستبدل الموعد السابق بعد نجاح الحفظ.','Choose a new time. The booking will await team confirmation, and the previous time is replaced only after saving succeeds.')).'</p>';
		self::form('reschedule',array('id'=>$id,'revision'=>\AutoDealership\Leads\RequestWorkflow::customer_revision($row)));PortalView::input('date','اليوم الجديد','New date',$row['requested_date'],'date','required min="'.esc_attr(wp_date('Y-m-d')).'" max="'.esc_attr(wp_date('Y-m-d',time()+$s['days']*DAY_IN_SECONDS)).'"');PortalView::input('time','الوقت الجديد','New time',substr($row['requested_time'],0,5),'time','required step="1800" min="'.sprintf('%02d:00',$s['start']).'" max="'.sprintf('%02d:30',$s['end']-1).'"');echo '<p class="adc-p-help">'.esc_html(sprintf(PortalAccess::t('حسب توقيت الموقع %s، وبفاصل إشعار لا يقل عن %d ساعات.','Site timezone: %s; at least %d hours notice is required.'),wp_timezone_string(),$s['notice'])).'</p>';PortalView::button('حفظ الموعد وإرساله للتأكيد','Save time & request confirmation');echo '</form></details>';
	}
	public static function upload(int $sale,string $kind,string $title,string $reference,array $file) {
		global $wpdb;$title=sanitize_text_field($title);$reference=sanitize_text_field($reference);$record=self::sale($sale,true);if(!$record||!in_array($kind,array('contract','invoice'),true)||!trim($title)||mb_strlen($title)>190||!trim($reference)||mb_strlen($reference)>100){return PortalAccess::error('adc_portal_forbidden',403);}if(!(int)$record['account_user_id']){return new \WP_Error('adc_document_unlinked',PortalAccess::t('اربط ملف العميل بحسابه المؤكد قبل إتاحة المستند.','Link the customer record to their account before sharing documents.'));}
		if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_uploaded_file($file['tmp_name']??'')||($file['size']??0)<8||($file['size']??0)>5*1024*1024){return PortalAccess::error('adc_portal_input');}
		if(!class_exists('finfo')){return new \WP_Error('adc_document_mime_unavailable',PortalAccess::t('فحص نوع الملفات غير متاح حاليًا. يرجى التواصل مع مسؤول النظام.','File type verification is unavailable. Please contact the administrator.'),array('status'=>503));}
		$bytes=file_get_contents($file['tmp_name']);$packet=(int)$wpdb->get_var('SELECT @@max_allowed_packet');if(false===$bytes||strlen($bytes)>min(5*1024*1024,max(0,$packet-65536))||!str_starts_with($bytes,'%PDF-')||'application/pdf'!==(new \finfo(FILEINFO_MIME_TYPE))->buffer($bytes)){return PortalAccess::error('adc_portal_input');}
		if(!Transaction::begin()){return PortalAccess::error();}
		if(!self::sale($sale,true)){$wpdb->query('ROLLBACK');return PortalAccess::error('adc_portal_forbidden',403);}
		$ok=$wpdb->insert(PortalAccess::table('documents'),array('sale_id'=>$sale,'kind'=>$kind,'title'=>sanitize_text_field($title),'reference'=>sanitize_text_field($reference),'content_hash'=>hash('sha256',$bytes),'file_bytes'=>$bytes,'file_size'=>strlen($bytes),'created_by'=>get_current_user_id(),'created_at'=>current_time('mysql',true)));$id=(int)$wpdb->insert_id;
		if(false===$ok||!Transaction::commit(static fn()=>PortalAccess::audit('document_published','portal_document',$id,array('sale'=>$sale,'kind'=>$kind)))){$wpdb->query('ROLLBACK');return PortalAccess::error();}return $id;
	}
	public static function document(int $id,bool $staff=false):?array {
		global $wpdb;$row=$wpdb->get_row($wpdb->prepare('SELECT id,sale_id,kind,content_hash,file_bytes FROM '.PortalAccess::table('documents')." WHERE id=%d AND status='published'",$id),ARRAY_A);if(!$row||(!self::sale((int)$row['sale_id'])&&(! $staff||PortalAccess::personal_request()||!self::sale((int)$row['sale_id'],true)))){return null;}return $row;
	}
	public static function submit():void {
		if(!is_user_logged_in()){wp_die('Forbidden','',array('response'=>403));}check_admin_referer('adc_customer_journey');PortalAccess::request_scope('staff'===Portal::field('portal_scope')&&(current_user_can('manage_options')||current_user_can('adc_publish_customer_documents')));$op=Portal::field('operation');$result=PortalAccess::error('adc_portal_input');$section='overview';
		if(!PortalAccess::ready()){wp_die('Unavailable','',array('response'=>503));}
		if('favorite'===$op){$car=absint(Portal::field('car'));$saved='1'===Portal::field('save');$result=self::favorite($car,$saved);$section='favorites';if('icon'===Portal::field('favorite_ui')&&str_contains($_SERVER['HTTP_ACCEPT']??'','application/json')){nocache_headers();if(is_wp_error($result)){wp_send_json_error(array('message'=>$result->get_error_message()),(int)($result->get_error_data()['status']??400));}wp_send_json_success(array('car'=>$car,'saved'=>$saved,'message'=>PortalAccess::t($saved?'أُضيفت السيارة إلى المفضلة.':'أُزيلت السيارة من المفضلة.',$saved?'Car saved to favorites.':'Car removed from favorites.')));}}
		elseif('reschedule'===$op){$lead=\AutoDealership\Leads\RequestWorkflow::linked_lead('booking',absint(Portal::field('id')));$result=is_int($lead)?\AutoDealership\Leads\RequestWorkflow::update($lead,array('requested_date'=>Portal::field('date'),'requested_time'=>Portal::field('time'),'revision'=>Portal::field('revision')),false,true):PortalAccess::error('adc_portal_input');$section='bookings';}
		elseif('upload'===$op){$result=PortalAccess::personal_request()?PortalAccess::error('adc_portal_forbidden',403):self::upload(absint(Portal::field('sale')),Portal::field('kind'),Portal::field('title'),Portal::field('reference'),$_FILES['document']??array());$section='documents';}
		elseif('revoke'===$op){global $wpdb;$row=self::document(absint(Portal::field('id')),true);if(!PortalAccess::personal_request()&&$row&&self::sale((int)$row['sale_id'],true)&&Transaction::begin()){$result=$wpdb->update(PortalAccess::table('documents'),array('status'=>'revoked'),array('id'=>$row['id']));if(false===$result||!Transaction::commit(static fn()=>PortalAccess::audit('document_revoked','portal_document',(int)$row['id']))){$wpdb->query('ROLLBACK');$result=PortalAccess::error();}}$section='documents';}
		elseif('download'===$op){$row=self::document(absint(Portal::field('id')),!PortalAccess::personal_request());if(!$row||!hash_equals($row['content_hash'],hash('sha256',$row['file_bytes']))){wp_die('Not found','',array('response'=>404));}if(!PortalAccess::audit('document_downloaded','portal_document',(int)$row['id'])){wp_die('Unavailable','',array('response'=>503));}nocache_headers();header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.$row['kind'].'-'.(int)$row['id'].'.pdf"');header('X-Content-Type-Options: nosniff');header('Content-Security-Policy: sandbox');header('Content-Length: '.strlen($row['file_bytes']));echo $row['file_bytes'];exit;}
		set_transient('adc_portal_flash_'.get_current_user_id(),array('error'=>is_wp_error($result),'message'=>is_wp_error($result)?$result->get_error_message():PortalAccess::t('تم حفظ طلبك بنجاح.','Your request was saved successfully.')),60);
		$url=in_array($op,array('upload','revoke'),true)?admin_url('admin.php?page=adc-portal-operations&tab=documents'):PortalAccess::url($section);wp_safe_redirect($url,303);exit;
	}
}
